{"path": "/tmp/sv-27198610a7994181b312e18cf188e666/Components/Chat/ChatPage.razor", "file_text": "@page "/chat"
@rendermode InteractiveServer
@using sv_27198610a7994181b312e18cf188e666.Services
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <div class="chat-sidebar">
        <ChannelSidebar Channels="channels"
                        SelectedChannelId="selectedChannelId"
                        OnChannelSelected="SelectChannel" />
    </div>

    <div class="chat-main">
        @if (selectedChannel is not null)
        {
            <MessageArea Channel="selectedChannel"
                         Messages="messages"
                         ThreadSummaries="threadSummaries"
                         HasMoreMessages="hasMoreMessages"
                         IsLoadingMore="isLoadingMore"
                         OnLoadMore="LoadMoreMessages"
                         OnSendMessage="SendMessage"
                         OnOpenThread="OpenThread"
                         OnReact="AddReaction" />
        }
    </div>

    @if (isThreadOpen)
    {
        <div class="chat-thread">
            <ThreadPanel RootMessage="threadRootMessage"
                         Replies="threadReplies"
                         OnClose="CloseThread"
                         OnSendReply="SendThreadReply" />
        </div>
    }
</div>

@code {
    private List<Channel> channels = [];
    private Channel? selectedChannel;
    private int selectedChannelId;
    private List<Message> messages = [];
    private Dictionary<int, ThreadSummary> threadSummaries = new();
    private bool hasMoreMessages = true;
    private bool isLoadingMore;
    private const int PageSize = 50;

    private bool isThreadOpen;
    private Message? threadRootMessage;
    private List<Message> threadReplies = [];

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        selectedChannelId = channelId;
        selectedChannel = channels.FirstOrDefault(c => c.Id == channelId);
        messages = [];
        threadSummaries = new();
        hasMoreMessages = true;
        CloseThreadInternal();

        var loaded = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        messages = loaded;
        hasMoreMessages = loaded.Count == PageSize;
        ComputeThreadSummaries();
        await ChatService.MarkChannelReadAsync(channelId);

        // Update the channel's unread count locally
        var idx = channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            channels[idx] = channels[idx] with { UnreadCount = 0 };
        }
    }

    private async Task LoadMoreMessages()
    {
        if (isLoadingMore || selectedChannel is null) return;
        isLoadingMore = true;

        var older = await ChatService.GetMessagesAsync(selectedChannel.Id, messages.Count, PageSize);
        messages.InsertRange(0, older);
        hasMoreMessages = older.Count == PageSize;
        ComputeThreadSummaries();
        isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        if (selectedChannel is null) return;
        var msg = await ChatService.SendMessageAsync(selectedChannel.Id, content, null);
        messages.Add(msg);
    }

    private async Task OpenThread(int rootMessageId)
    {
        threadRootMessage = messages.FirstOrDefault(m => m.Id == rootMessageId);
        if (threadRootMessage is null) return;

        var thread = await ChatService.GetThreadAsync(rootMessageId);
        threadReplies = thread.Where(m => m.Id != rootMessageId).ToList();
        isThreadOpen = true;

        if (threadReplies.Count > 0)
        {
            threadSummaries[rootMessageId] = new ThreadSummary(
                rootMessageId, threadReplies.Count, threadReplies[^1].SentAt);
        }
    }

    private async Task SendThreadReply(string content)
    {
        if (threadRootMessage is null || selectedChannel is null) return;
        var reply = await ChatService.SendMessageAsync(selectedChannel.Id, content, threadRootMessage.Id);
        threadReplies.Add(reply);
        threadSummaries[threadRootMessage.Id] = new ThreadSummary(
            threadRootMessage.Id, threadReplies.Count, reply.SentAt);
    }

    private async Task AddReaction((int MessageId, string Emoji) reaction)
    {
        await ChatService.AddReactionAsync(reaction.MessageId, reaction.Emoji);

        var msg = messages.FirstOrDefault(m => m.Id == reaction.MessageId);
        if (msg is null) return;

        var existing = msg.Reactions.FirstOrDefault(r => r.Emoji == reaction.Emoji);
        if (existing is not null)
        {
            if (!existing.Users.Contains("You"))
            {
                existing.Users.Add("You");
            }
        }
        else
        {
            msg.Reactions.Add(new Reaction(reaction.Emoji, ["You"]));
        }
    }

    private void CloseThread() => CloseThreadInternal();

    private void CloseThreadInternal()
    {
        isThreadOpen = false;
        threadRootMessage = null;
        threadReplies = [];
    }

    private void ComputeThreadSummaries()
    {
        var replyGroups = messages
            .Where(m => m.ReplyToId.HasValue)
            .GroupBy(m => m.ReplyToId!.Value);

        foreach (var group in replyGroups)
        {
            var replies = group.ToList();
            threadSummaries[group.Key] = new ThreadSummary(
                group.Key, replies.Count, replies.Max(r => r.SentAt));
        }
    }
}
"}

